using Godot;
using System;
using System.Collections.Generic;
public partial class ImageWorkspaceOperations
{
    public Vector2[] layer_polygon(Control owner,Resource layer)
    {
        string kind=layer.Get("kind").AsString();if(kind is not "shape" and not "path")return Array.Empty<Vector2>();var properties=layer.Get("properties").AsGodotDictionary();var dimensions=layer.Get("dimensions").AsVector2();string shape=Get(properties,"shape",kind=="path"?"custom":"rectangle").AsString();Vector2[] points;if(shape=="ellipse"){points=new Vector2[64];for(int i=0;i<64;i++)points[i]=dimensions*.5f+Vector2.FromAngle(Mathf.Tau*i/64)*dimensions*.5f;}else if(shape=="triangle")points=new[]{new Vector2(dimensions.X*.5f,0),dimensions,new Vector2(0,dimensions.Y)};else if(shape=="custom"||kind=="path"){points=Get(properties,"points",Array.Empty<Vector2>()).AsVector2Array();var source=Get(properties,"path_size",dimensions).AsVector2().Max(Vector2.One);for(int i=0;i<points.Length;i++)points[i]*=dimensions/source;}else points=new[]{Vector2.Zero,new Vector2(dimensions.X,0),dimensions,new Vector2(0,dimensions.Y)};var world=_documents.world_transform(Document(owner),layer);for(int i=0;i<points.Length;i++)points[i]=world*points[i];return points;
    }
    public void boolean_shapes(Control owner,string operation)
    {
        var document=Document(owner);var canvas=Canvas(owner);var layers=new List<Resource>();foreach(var id in canvas.Get("selected").AsGodotArray()){var layer=_documents.layer_for_id(document,id.AsString());if(layer!=null&&(layer.Get("kind").AsString() is "shape" or "path"))layers.Add(layer);}if(layers.Count<2){owner.Get("status").As<Label>().Text="Select at least two shape/path layers.";return;}var polygons=new List<Vector2[]>{layer_polygon(owner,layers[0])};for(int i=1;i<layers.Count;i++){var next=layer_polygon(owner,layers[i]);var combined=new List<Vector2[]>();foreach(var polygon in polygons){var pieces=operation=="union"?Geometry2D.MergePolygons(polygon,next):operation=="intersect"?Geometry2D.IntersectPolygons(polygon,next):Geometry2D.ClipPolygons(polygon,next);foreach(var piece in pieces)combined.Add(piece);}polygons=combined;}if(polygons.Count==0){owner.Get("status").As<Label>().Text="The boolean operation produced an empty shape.";return;}var created=new List<Resource>();foreach(var polygon in polygons){if(polygon.Length<3)continue;var bounds=new Rect2(polygon[0],Vector2.Zero);foreach(var point in polygon)bounds=bounds.Expand(point);var result=_layers.create("path",document.Get("canvas_size").AsVector2I());result.Set("label",operation.Capitalize()+" shape");result.Set("position",bounds.Position);result.Set("dimensions",bounds.Size.Max(Vector2.One));var local=new Vector2[polygon.Length];for(int i=0;i<local.Length;i++)local[i]=polygon[i]-bounds.Position;var properties=result.Get("properties").AsGodotDictionary();properties["points"]=local;properties["path_size"]=result.Get("dimensions");properties["color"]=Get(layers[^1].Get("properties").AsGodotDictionary(),"color",Colors.White);created.Add(result);}Action(owner,()=>{var all=document.Get("layers").AsGodotArray();foreach(var layer in layers)all.Remove(layer);var selected=canvas.Get("selected").AsGodotArray();selected.Clear();foreach(var layer in created){all.Add(layer);selected.Add(layer.Get("id"));}});owner.Get("status").As<Label>().Text="Created "+operation+" vector result";
    }
}
